declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/app/autoload.php';
use FMonitor2\InstallationProcess\JobsSchemaMigration;use FMonitor2\Jobs\{JobHandlerRuntime,JobsRuntimeConfiguration,MariaDbEquipmentFactsScheduler};assertSameValue(true,class_exists(MariaDbEquipmentFactsScheduler::class),'INTENDED_RED hourly scheduler missing');$process=file_get_contents(dirname(__DIR__,2).'/app/Jobs/JobsSchedulerProcess.php');assertSameValue(true,str_contains($process,'MariaDbEquipmentFactsScheduler')&&str_contains($process,'equipmentFacts'),'existing scheduler process invokes equipment scheduler');$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$pass=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$name='t_erp_schedule_'.bin2hex(random_bytes(4));$a=new mysqli($host,$user,$pass,'',$port);$a->query("CREATE DATABASE `$name`");$db=new mysqli($host,$user,$pass,$name,$port);try{JobsSchemaMigration::apply($db,'es_');$s=new MariaDbEquipmentFactsScheduler($db,'es_');$one=$s->tick('2026-09-15T07:10:00.000000Z');$repeat=$s->tick('2026-09-15T07:59:59.000000Z');assertSameValue(['2026-09-15T10',true,$one['jobId'],false],[$one['slot'],$one['created'],$repeat['jobId'],$repeat['created']],'Moscow slot dedupe');$later=$s->tick('2026-09-15T11:05:00.000000Z');assertSameValue([true,3],[$later['created'],$later['skippedSlots']],'current only no backlog');$job=$db->query("SELECT job_type,payload_version,payload_json,actor_json FROM es_fm2_jobs WHERE job_id=".(int)$later['jobId'])->fetch_assoc();assertSameValue(['erp.equipment-facts.sync',1,['scheduleSlot'=>'2026-09-15T14'],['id'=>'erp-equipment-facts-hourly-v1','type'=>'system']],[$job['job_type'],(int)$job['payload_version'],json_decode($job['payload_json'],true),json_decode($job['actor_json'],true)],'versioned minimal job');$release=sys_get_temp_dir().'/erp-scheduler-release-'.bin2hex(random_bytes(4));$children=[];for($i=0;$i<2;$i++){$pipes=[];$proc=proc_open([PHP_BINARY,dirname(__DIR__).'/Support/equipment_facts_scheduler_worker.php',$name,$release],[0=>['file','/dev/null','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2));$children[]=[$proc,$pipes];}touch($release);$created=[];$ids=[];foreach($children as[$proc,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);assertSameValue([0,''],[proc_close($proc),$err],'concurrent tick success');$r=json_decode($out,true,512,JSON_THROW_ON_ERROR);$created[]=$r['created'];$ids[]=$r['jobId'];}unlink($release);sort($created);assertSameValue([false,true],$created,'concurrent same-slot single creation');assertSameValue(1,count(array_unique($ids)),'concurrent same-slot same job');$config=(new ReflectionClass(JobsRuntimeConfiguration::class))->newInstanceWithoutConstructor();$calls=0;$ok=JobHandlerRuntime::handle(['jobType'=>'erp.equipment-facts.sync','payloadVersion'=>1,'payload'=>['scheduleSlot'=>'2026-09-15T14']],$config,static function()use(&$calls){$calls++;return['status'=>'completed','runId'=>'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','matched'=>2];});assertSameValue(['completed',['runId'=>'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','matched'=>2],1],[$ok['status'],$ok['result'],$calls],'worker canonical dispatch');$fail=JobHandlerRuntime::handle(['jobType'=>'erp.equipment-facts.sync','payloadVersion'=>1,'payload'=>['scheduleSlot'=>'2026-09-15T14']],$config,static fn()=>['status'=>'failed','runId'=>'cccccccc-cccc-4ccc-8ccc-cccccccccccc','reason'=>'SOURCE_UNAVAILABLE']);assertSameValue(['retryable','ERP_EQUIPMENT_FACTS_SYNC_FAILED',['runId'=>'cccccccc-cccc-4ccc-8ccc-cccccccccccc','reason'=>'SOURCE_UNAVAILABLE']],[$fail['status'],$fail['failureCode'],$fail['result']??null],'failure retryable with safe provenance');$thrown=JobHandlerRuntime::handle(['jobType'=>'erp.equipment-facts.sync','payloadVersion'=>1,'payload'=>['scheduleSlot'=>'2026-09-15T14']],$config,static function(){throw new RuntimeException('PRIVATE SOURCE mysql:host=secret password=secret SELECT * FROM source');});assertSameValue(['status'=>'retryable','failureCode'=>'ERP_EQUIPMENT_FACTS_SYNC_FAILED'],$thrown,'thrown composition exact safe shape without fabricated persisted run');$serialized=json_encode($thrown,JSON_THROW_ON_ERROR);foreach(['PRIVATE SOURCE','mysql:','password','SELECT ']as$forbidden){assertSameValue(false,str_contains($serialized,$forbidden),'thrown composition does not leak '.$forbidden);}echo"PASS: ERP-EQUIPMENT-FACTS-001 hourly runtime\n";}finally{$db->close();$a->query("DROP DATABASE IF EXISTS `$name`");$a->close();}
